<!DOCTYPE html><html lang="sr"><head><meta charset="utf-8"><title>Račun {{ $invoice->invoice_number }}</title><style>@page{margin:0}*{box-sizing:border-box}body{margin:0;color:#25233d;font-family:DejaVu Sans Mono,monospace;font-size:7.5pt}.p{padding:11mm 14mm 18mm}.bar{padding:3mm 5mm;background:#4f46e5;color:#fff}.screen{padding:8mm;border:2px solid #4f46e5;border-top:0;background:#f7f7ff}.h{margin:4px 0;font-size:18pt;font-weight:bold}.violet{color:#4f46e5}.t,.items,.sum{width:100%;border-collapse:collapse}.t{margin:6mm 0}.t>tbody>tr>td{width:50%;padding:6px;border:1px solid #c7d2fe}.client{margin:4px 0;font-size:10pt;font-weight:bold}.mute{color:#73708e;line-height:1.45}.items th{padding:6px 4px;background:#e0e7ff;color:#3730a3;text-align:left;font-size:6pt}.items td{padding:7px 4px;border-bottom:1px solid #dbe1ff;vertical-align:top}.r{text-align:right;white-space:nowrap}.ct{text-align:center}.sum{width:43%;margin:7mm 0 0 auto;border:1px solid #a5b4fc}.sum td{padding:6px;border-top:1px solid #c7d2fe}.sum td:last-child{text-align:right;font-weight:bold}.total td{background:#4f46e5;color:#fff;font-size:11pt}.box{margin-top:7mm;padding:7px;border:1px solid #c7d2fe;background:#eef2ff;white-space:pre-line}.foot{position:fixed;right:14mm;bottom:7mm;left:14mm;color:#9894b6;font-size:6pt}</style></head><body><div class="p"><div class="bar">RADNA_STANICA :: dokument / aktivan</div><div class="screen"><div class="violet">[01] IZDAVALAC</div><div class="h">{{ $company->name }}</div><div class="mute">{{ $company->address }} · {{ $company->zip }} {{ $company->city }}@if($company->identification_number)<br>JIB: {{ $company->identification_number }}@endif</div><div class="violet" style="margin-top:6px">[02] RAČUN {{ $invoice->invoice_number }} · {{ $invoice->date?->format('d.m.Y.') }}</div><table class="t"><tr><td><div class="violet">[03] KUPAC</div><div class="client">{{ $invoice->client?->name ?? '—' }}</div><div class="mute">{{ $invoice->client?->address }}<br>{{ $invoice->client?->zip }} {{ $invoice->client?->city }}</div></td><td><div class="violet">[04] PLAĆANJE</div><div class="mute">rok: <strong>{{ $invoice->due_date?->format('d.m.Y.') ?? '—' }}</strong><br>način: <strong>{{ $invoice->payment_type?->label() ?? '—' }}</strong><br>valuta: <strong>{{ $invoice->currency }}</strong></div></td></tr></table><table class="items"><thead><tr><th>#</th><th style="width:43%">stavka</th><th class="ct">jm</th><th class="r">kol.</th><th class="r">cijena</th>@if($vat)<th class="r">pdv</th>@endif<th class="r">iznos</th></tr></thead><tbody>@foreach($invoice->items as $i=>$item) @php($q=max(1,(int)$item->quantity))<tr><td>{{ $i+1 }}</td><td><strong>{{ $item->name }}</strong>@if($item->description)<div class="mute">{{ $item->description }}</div>@endif</td><td class="ct">{{ $item->unit?->value }}</td><td class="r">{{ $item->quantity }}</td><td class="r">{{ $f((int)round($item->total/$q)) }} {{ $c }}</td>@if($vat)<td class="r">{{ number_format($item->tax_rate/100,2,',','.') }}%</td>@endif<td class="r"><strong>{{ $f($item->total) }} {{ $c }}</strong></td></tr>@endforeach</tbody></table><table class="sum"><tr><td>osnovica</td><td>{{ $f($invoice->subtotal) }} {{ $c }}</td></tr>@if($vat)<tr><td>pdv</td><td>{{ $f($invoice->tax_total) }} {{ $c }}</td></tr>@endif<tr class="total"><td>ukupno</td><td>{{ $f($invoice->total) }} {{ $c }}</td></tr></table>@if($invoice->notes)<div class="box"><span class="violet">[05] NAPOMENA</span><br>{{ $invoice->notes }}</div>@endif<div class="box"><span class="violet">[06] PODACI ZA PLAĆANJE</span><br>@forelse($bankAccounts as $a)<strong>{{ $a->bank_name }}</strong> · {{ $a->account_number }}<br>@empty<span class="mute">Podaci za bankovni račun nisu uneseni.</span>@endforelse</div></div></div><div class="foot">radna stanica / dokument sačuvan / {{ $invoice->invoice_number }}</div></body></html>
